<template>
  <main class="feedback-page" :aria-busy="loading">
    <header><p class="eyebrow">ITSCO · Support email review</p><h1>{{ report?.batch?.title || 'Reply quality review' }}</h1><p>Review what arrived, what the team sent, and the draft saved by the portal. Rate each available response, then add the wording or details you would prefer.</p></header>
    <p v-if="loading" role="status">Loading your review…</p>
    <p v-if="error" class="notice error" role="alert">{{ error }}</p>
    <template v-if="report">
      <section class="overview" aria-label="Review progress">
        <div><strong>{{ reviewed }} / {{ report.rows.length }} reviewed</strong><p>{{ formatTime(report.window.start) }} – {{ formatTime(report.window.end) }} · Mountain time</p><p>{{ report.totals.tickets }} conversations · {{ report.totals.sent }} confirmed replies · {{ report.totals.drafts }} captured drafts</p></div>
        <div><span v-if="report.batch.completedAt" class="complete" role="status">Review complete · feedback saved</span><button v-else type="button" :disabled="reviewed !== report.rows.length || hasUnsaved || completing" @click="finish">{{ completing ? 'Finishing…' : 'Finish review' }}</button><p class="hint">You can save an item and return later.</p></div>
      </section>
      <details class="coverage"><summary>About this review’s evidence</summary><p>This is a saved review of recorded support emails. A missing historical draft is marked unavailable; it has not been recreated. A closed ticket alone does not confirm an email was sent.</p><p>{{ report.coverage.personalMailboxReplies }}</p><p>{{ report.coverage.historicalDrafts }}</p><p v-if="report.coverage.conversationsWithoutReplyOrDraft">{{ report.coverage.conversationsWithoutReplyOrDraft }} other recorded conversations had no confirmed reply or readable captured draft to rate.</p><p>Ratings and written feedback stay in the app for improving future drafts.</p></details>
      <nav class="filters" aria-label="Review filters"><label>Show <select v-model="filter" @change="page=1"><option value="all">All items</option><option value="remaining">Still to review</option><option value="reviewed">Reviewed</option></select></label><span>{{ filtered.length }} items · {{ Object.values(dirty).filter(Boolean).length }} with unsaved changes</span></nav>
      <p v-if="!filtered.length" class="notice">No items in this view.</p>
      <article v-for="row in visible" :key="row.entryId" class="review-item" :aria-labelledby="`item-${row.entryId}`">
        <header class="item-heading"><div><span class="eyebrow">Ticket #{{ row.ticketId }} · Review item #{{ row.entryId }}</span><h2 :id="`item-${row.entryId}`">{{ row.subject || 'Email conversation' }}</h2><p>Claimed by {{ row.owner?.name || 'No recorded owner' }}</p></div><span class="status">{{ dirty[row.entryId] ? 'Unsaved changes' : row.feedback.reviewedAt ? 'Reviewed' : 'To review' }}</span></header>
        <div class="comparison">
          <section><h3>1. Email received</h3><p class="meta">From: {{ sender(row.originalReceived) }}<br>{{ formatTime(row.originalReceived?.receivedAt) }}</p><pre v-if="row.originalReceived?.body">{{ row.originalReceived.body }}</pre><p v-else class="unavailable">Original received email unavailable.</p></section>
          <section><h3>2. Actual reply</h3><template v-if="row.deliveries.length"><p class="meta">Replied by: {{ responder(row.deliveries[0]) }}<br>{{ formatTime(row.deliveries[0].occurredAt) }}</p><pre>{{ row.deliveries[0].body || 'Sent body unavailable.' }}</pre></template><p v-else class="unavailable">No confirmed sent reply for this item.</p></section>
          <section><h3>3. Portal’s saved draft</h3><template v-if="row.comparison.generatedDraft"><p class="meta">Saved {{ formatTime(row.draftSnapshots[0]?.createdAt) }}<br>Captured before staff edits</p><pre>{{ row.comparison.generatedDraft }}</pre></template><p v-else class="unavailable">No readable original draft was captured. There is no draft to rate.</p></section>
        </div>
        <form class="rating-form" @submit.prevent="save(row)">
          <div class="rating-columns">
            <fieldset :disabled="!row.canRateActual || !!report.batch.completedAt || saving[row.entryId]"><legend>How was the actual reply?</legend><label v-for="choice in choices" :key="choice.value"><input v-model="forms[row.entryId].actualRating" type="radio" :name="`actual-${row.entryId}`" :value="choice.value" @change="markDirty(row)" /> {{ choice.label }}</label><p v-if="!row.canRateActual" class="hint">No available reply to rate.</p></fieldset>
            <fieldset :disabled="!row.canRateDraft || !!report.batch.completedAt || saving[row.entryId]"><legend>How was the portal draft?</legend><label v-for="choice in choices" :key="choice.value"><input v-model="forms[row.entryId].draftRating" type="radio" :name="`draft-${row.entryId}`" :value="choice.value" @change="markDirty(row)" /> {{ choice.label }}</label><p v-if="!row.canRateDraft" class="hint">No captured draft to rate.</p></fieldset>
          </div>
          <div class="writing"><label :for="`preferred-${row.entryId}`">What would you like the reply to say? <span>(optional)</span></label><textarea :id="`preferred-${row.entryId}`" v-model="forms[row.entryId].preferredReply" rows="4" maxlength="12000" :disabled="!!report.batch.completedAt || saving[row.entryId]" placeholder="Write the response you would prefer…" @input="markDirty(row)"></textarea><label :for="`notes-${row.entryId}`">What should it include or change? <span>(optional)</span></label><textarea :id="`notes-${row.entryId}`" v-model="forms[row.entryId].notes" rows="3" maxlength="12000" :disabled="!!report.batch.completedAt || saving[row.entryId]" placeholder="Missing details, tone, facts to check, or anything to avoid…" @input="markDirty(row)"></textarea></div>
          <footer><button v-if="!report.batch.completedAt" type="submit" :disabled="!dirty[row.entryId] || saving[row.entryId]">{{ saving[row.entryId] ? 'Saving…' : 'Save feedback' }}</button><span v-if="saved[row.entryId] && !dirty[row.entryId]" role="status">Saved in the app.</span><span v-if="itemErrors[row.entryId]" class="error" role="alert">{{ itemErrors[row.entryId] }}</span></footer>
        </form>
      </article>
      <nav v-if="pages>1" class="pagination" aria-label="Review pages"><button :disabled="page<=1" @click="page--">Previous</button><span>Page {{ page }} of {{ pages }}</span><button :disabled="page>=pages" @click="page++">Next</button></nav>
    </template>
  </main>
</template>
<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useRoute,onBeforeRouteLeave} from 'vue-router';
import api from '../../services/api';
const route=useRoute();
const report=ref(null),loading=ref(false),error=ref(''),forms=ref({}),dirty=ref({}),saving=ref({}),saved=ref({}),itemErrors=ref({}),completing=ref(false),filter=ref('all'),page=ref(1);
const choices=[{value:'good',label:'Good'},{value:'acceptable',label:'Acceptable'},{value:'bad',label:'Bad'}];
const agencyId=computed(()=>Number(route.query.agencyId)),batchId=computed(()=>Number(route.query.batch));
const reviewed=computed(()=>(report.value?.rows || []).filter(r=>r.feedback.reviewedAt).length);
const hasUnsaved=computed(()=>Object.values(dirty.value).some(Boolean));
const filtered=computed(()=>(report.value?.rows || []).filter(r=>filter.value==='all'||(filter.value==='reviewed'?!!r.feedback.reviewedAt:!r.feedback.reviewedAt)));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/8)));
const visible=computed(()=>filtered.value.slice((page.value-1)*8,page.value*8));
watch(pages,n=>{if(page.value>n)page.value=n;});
function formatTime(value){if(!value)return 'Time not recorded';const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('en-US',{timeZone:'America/Denver',year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d):'Time not recorded';}
const sender=s=>[s?.fromName,s?.fromEmail].filter(Boolean).join(' · ')||'Sender not recorded';
const responder=d=>[d?.actorName,d?.fromEmail].filter(Boolean).join(' · ')||'Responder not recorded';
const markDirty=row=>{dirty.value[row.entryId]=true;itemErrors.value[row.entryId]='';};
function unload(event){if(hasUnsaved.value){event.preventDefault();event.returnValue='';}}
let version=0;
async function load(){const current=++version;loading.value=true;error.value='';try{const {data}=await api.get(`/support-email-review/batches/${batchId.value}`,{params:{agencyId:agencyId.value},skipGlobalLoading:true});if(version!==current)return;report.value=data;forms.value=Object.fromEntries(data.rows.map(r=>[r.entryId,{actualRating:r.feedback.actualRating||null,draftRating:r.feedback.draftRating||null,preferredReply:r.feedback.preferredReply||'',notes:r.feedback.notes||'',revision:r.feedback.revision}]));dirty.value={};saved.value={};itemErrors.value={};page.value=1;}catch(e){if(version===current)error.value=e?.response?.data?.error?.message||'The review could not be loaded. Please try again.';}finally{if(version===current)loading.value=false;}}
async function save(row){const key=row.entryId;saving.value[key]=true;itemErrors.value[key]='';const current=version;try{const {data}=await api.put(`/support-email-review/batches/${batchId.value}/entries/${key}`,{agencyId:agencyId.value,...forms.value[key]},{skipGlobalLoading:true});if(current!==version)return;row.feedback=data.feedback;forms.value[key]={...forms.value[key],...data.feedback};dirty.value[key]=false;saved.value[key]=true;}catch(e){if(current===version)itemErrors.value[key]=e?.response?.data?.error?.message||'Could not save. Your text is still here; please try again.';}finally{if(current===version)saving.value[key]=false;}}
async function finish(){if(hasUnsaved.value)return;completing.value=true;error.value='';try{await api.post(`/support-email-review/batches/${batchId.value}/complete`,{agencyId:agencyId.value});report.value.batch.completedAt=new Date().toISOString();}catch(e){error.value=e?.response?.data?.error?.message||'The review could not be marked complete.';}finally{completing.value=false;}}
watch([agencyId,batchId],load,{immediate:true});
onBeforeRouteLeave(()=>!hasUnsaved.value || window.confirm('You have unsaved feedback. Leave without saving?'));
onMounted(()=>window.addEventListener('beforeunload',unload));
onBeforeUnmount(()=>{version++;window.removeEventListener('beforeunload',unload);});
</script>
<style scoped>
.feedback-page{max-width:1500px;margin:auto;padding:32px 28px 64px;color:var(--text-primary,#203249)}h1{font-size:30px;margin:7px 0 12px}h2{font-size:21px;margin:8px 0}h3{font-size:16px}.eyebrow{font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:var(--text-secondary,#627184)}header>p{max-width:840px;line-height:1.65}.overview,.filters,.item-heading,.pagination{display:flex;justify-content:space-between;align-items:center;gap:24px}.overview{padding:24px;margin:24px 0;background:var(--bg-secondary,#f1f5f7);border-radius:14px}.overview strong{font-size:24px}.overview p{margin:7px 0;font-size:14px}.hint,.meta,.unavailable{font-size:13px;line-height:1.6;color:var(--text-secondary,#627184)}.coverage{padding:16px 0;line-height:1.65}.coverage summary{cursor:pointer}.filters{margin:18px 0;color:var(--text-secondary,#627184);font-size:14px}select{padding:8px;margin-left:8px}.review-item{border:1px solid var(--border-color,#dbe3e9);border-radius:16px;margin:0 0 24px;overflow:hidden;background:var(--bg-primary,#fff)}.item-heading{padding:22px 24px}.item-heading p{font-size:13px;margin-bottom:0;color:var(--text-secondary,#627184)}.status{white-space:nowrap;border-radius:20px;padding:6px 12px;background:var(--bg-secondary,#f1f5f7);font-size:12px}.comparison{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid var(--border-color,#dbe3e9)}.comparison section{padding:20px 24px;min-width:0;border-right:1px solid var(--border-color,#dbe3e9)}.comparison section:last-child{border-right:0}.comparison pre{font-family:inherit;line-height:1.75;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto}.rating-form{border-top:1px solid var(--border-color,#dbe3e9);padding:24px;background:var(--bg-secondary,#f7f9fa)}.rating-columns{display:grid;grid-template-columns:1fr 1fr;gap:24px}fieldset{border:0;padding:0;margin:0}legend{font-weight:600;margin-bottom:12px}fieldset label{display:inline-flex;align-items:center;gap:6px;padding:9px 12px 9px 0;font-size:14px}input[type=radio]{width:18px;height:18px;accent-color:#2d5b61}.writing{display:grid;gap:10px;margin-top:22px}.writing label{font-size:14px;font-weight:600}.writing label span{font-weight:400;color:var(--text-secondary,#627184)}textarea{box-sizing:border-box;width:100%;border:1px solid var(--border-color,#cad6df);border-radius:8px;padding:12px;font:inherit;background:var(--bg-primary,#fff);color:inherit;resize:vertical}footer{display:flex;align-items:center;gap:16px;margin-top:18px;font-size:13px}button{border:0;border-radius:8px;background:#254f58;color:white;padding:11px 18px;cursor:pointer;font:inherit;font-size:14px}button:disabled{opacity:.5;cursor:default}.error{color:#a63131}.notice{padding:16px;background:var(--bg-secondary,#f3f6f8);border-radius:8px}.complete{color:#23614e;font-weight:600}.pagination{justify-content:center;margin-top:24px}fieldset:disabled{opacity:.6}@media(max-width:900px){.comparison{grid-template-columns:1fr}.comparison section{border-right:0;border-bottom:1px solid var(--border-color,#dbe3e9)}}@media(max-width:600px){.feedback-page{padding:22px 14px 50px}.overview,.item-heading,.filters{align-items:flex-start;flex-direction:column;gap:14px}.rating-columns{grid-template-columns:1fr}.item-heading,.comparison section,.rating-form{padding:18px}.overview strong{font-size:22px}h1{font-size:26px}footer{flex-wrap:wrap}}
</style>
